using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Runtime.Serialization;using System.ComponentModel;using System.Globalization;
namespace CircuitoStudio {
[DataContract]public sealed class EnclosureRating {
[DataMember]public string Manufacturer{get;set;}[DataMember]public string Reference{get;set;}[DataMember]public string Variant{get;set;}[DataMember]public double WidthMm{get;set;}[DataMember]public double HeightMm{get;set;}[DataMember]public double DepthMm{get;set;}[DataMember]public int Rows{get;set;}[DataMember]public int ModulesPerRow{get;set;}[DataMember]public double ModulePitchMm{get;set;}[DataMember]public double RowPitchMm{get;set;}[DataMember]public double? AnnotatedMaxCurrentA{get;set;}[DataMember]public double? AnnotatedDissipationW{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string DocumentSha256{get;set;}[DataMember]public string Conditions{get;set;}
public EnclosureRating(){Manufacturer=Reference=Variant=Source=DataVersion=DocumentSha256=Conditions="";}public EnclosureRating Copy(){return (EnclosureRating)MemberwiseClone();}public EnclosureSpec Spec(){return new EnclosureSpec{WidthMm=WidthMm,HeightMm=HeightMm,Rows=Rows,ModulesPerRow=ModulesPerRow,ModulePitchMm=ModulePitchMm,RowPitchMm=RowPitchMm,Manufacturer=Manufacturer,Reference=Reference};}public void Validate(){foreach(var s in new[]{Manufacturer,Reference,Variant,Source,DataVersion,DocumentSha256,Conditions})ReturnSizing.Text(s,false);if(!Enclosures.SpecValid(Spec()))throw new InvalidDataException("Geometria/capacidade do catálogo inválidas.");Project.Range(DepthMm,.001,100000,"profundidade externa");foreach(var x in new[]{AnnotatedMaxCurrentA,AnnotatedDissipationW})if(x.HasValue)Project.Range(x.Value,0,1e12,"limite anotado do invólucro");}
}
[DataContract]public sealed class EnclosureCatalogBinding{[DataMember]public string Engine{get;set;}[DataMember]public EnclosureRating Rating{get;set;}public EnclosureCatalogBinding(){Engine=EnclosureCatalog.EngineId;}public EnclosureCatalogBinding Copy(){return new EnclosureCatalogBinding{Engine=Engine,Rating=Rating==null?null:Rating.Copy()};}public void Validate(){if(Engine!=EnclosureCatalog.EngineId)throw new InvalidDataException("Motor do catálogo de invólucros desconhecido.");if(Rating!=null)Rating.Validate();}}
[DataContract]public sealed class DinFootprint {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Passo do módulo do envelope (mm)")]public double ModulePitchMm{get;set;}[DataMember,DisplayName("Largura TOTAL ocupada (módulos)")]public int WidthModules{get;set;}[DataMember,DisplayName("Equipamentos/conjunto que compõem o envelope")]public string Equipment{get;set;}[DataMember,DisplayName("Documento/dimensão/página da largura")]public string Reference{get;set;}[DataMember,DisplayName("Revisão dos dados")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições/cobertura/folgas declaradas")]public string Conditions{get;set;}[DataMember,DisplayName("Envelope inclui todos os acessórios selecionados")]public bool? CoversAccessories{get;set;}[DataMember,Browsable(false)]public string HardwareContext{get;set;}
public DinFootprint(){ModulePitchMm=17.5;Engine=EnclosureCatalog.EngineId;Equipment=Reference=DataVersion=Conditions=HardwareContext="";}public DinFootprint Copy(){return (DinFootprint)MemberwiseClone();}public void Validate(){if(Engine!=EnclosureCatalog.EngineId)throw new InvalidDataException("Motor do envelopeDIN desconhecido.");Project.Range(WidthModules,1,1000,"módulos do envelopeDIN");Project.Range(ModulePitchMm,.001,100000,"passo do envelope DIN");foreach(var s in new[]{Equipment,Reference,DataVersion,Conditions,HardwareContext})ReturnSizing.Text(s,false);}
}
public sealed class EnclosureCatalogResult {public bool Accepted;public string Status,Detail;public List<string> Issues=new List<string>();}
public static class EnclosureCatalog {
public const string EngineId="cs-involucro-catalogo-v1";public const string Header="Manufacturer;Reference;Variant;WidthMm;HeightMm;DepthMm;Rows;ModulesPerRow;ModulePitchMm;RowPitchMm;AnnotatedMaxCurrentA;AnnotatedDissipationW;Source;DataVersion;DocumentSha256;Conditions";
static bool Trace(string s){return !String.IsNullOrWhiteSpace(s)&&!s.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase);}static bool Hash(string s){return s!=null&&s.Length==64&&s.All(x=>Uri.IsHexDigit(x));}
public static string Hardware(Circuit c){return ProtectionResponses.Hash(new[]{c.BreakerA.ToString("R",CultureInfo.InvariantCulture),ProtectionResponses.Hash(c.Protection),ProtectionResponses.Hash(c.SwitchgearSelection),ProtectionResponses.Hash(c.ResidualSelection),ProtectionResponses.Hash(c.MotorStarterSelection)});}
public static List<EnclosureRating> ReferenceCatalog(){return new List<EnclosureRating>{new EnclosureRating{Manufacturer="ABB",Reference="1SPE007717F0410",Variant="Mistral 41W, sobrepor, porta opaca, ensaio ao fio incandescente 650 °C",WidthMm=297,HeightMm=262,DepthMm=119,Rows=1,ModulesPerRow=12,ModulePitchMm=17.5,RowPitchMm=125,AnnotatedMaxCurrentA=63,AnnotatedDissipationW=23.8,Source="ABB1TXH000327C0301 p14(rail pitch also p13); https://library.e.abb.com/public/0f1dd4cc71ec47f098a2b9b50f2cf5af/1TXH000327C0301_Coffrets%20Mistral.pdf",DataVersion="09/2014",DocumentSha256="753034781e5def7bbd2e1e5a9d8fd8f423254f603596fc74e1b2cf55653887d6",Conditions="Capacidade e dimensões externas do catálogo; módulo de 17,5 mm; passo entre trilhos de 125 mm, sem uso em um trilho; origem e altura desenhadas são esquemáticas, sem cotas de furação OEM; sem certificação térmica/IP"},new EnclosureRating{Manufacturer="ABB",Reference="1SPE007717F0510",Variant="Mistral 41W, sobrepor, porta opaca, ensaio ao fio incandescente 650 °C",WidthMm=297,HeightMm=387,DepthMm=119,Rows=2,ModulesPerRow=12,ModulePitchMm=17.5,RowPitchMm=125,AnnotatedMaxCurrentA=63,AnnotatedDissipationW=30.2,Source="ABB1TXH000327C0301 p14(rail pitch also p13); https://library.e.abb.com/public/0f1dd4cc71ec47f098a2b9b50f2cf5af/1TXH000327C0301_Coffrets%20Mistral.pdf",DataVersion="09/2014",DocumentSha256="753034781e5def7bbd2e1e5a9d8fd8f423254f603596fc74e1b2cf55653887d6",Conditions="Capacidade e dimensões externas do catálogo; módulo de 17,5 mm; passo entre trilhos de 125 mm, sem uso em um trilho; origem e altura desenhadas são esquemáticas, sem cotas de furação OEM; sem certificação térmica/IP"},new EnclosureRating{Manufacturer="ABB",Reference="1SPE007717F0610",Variant="Mistral 41W, sobrepor, porta opaca, ensaio ao fio incandescente 650 °C",WidthMm=297,HeightMm=512,DepthMm=119,Rows=3,ModulesPerRow=12,ModulePitchMm=17.5,RowPitchMm=125,AnnotatedMaxCurrentA=63,AnnotatedDissipationW=36.8,Source="ABB1TXH000327C0301 p14(rail pitch also p13); https://library.e.abb.com/public/0f1dd4cc71ec47f098a2b9b50f2cf5af/1TXH000327C0301_Coffrets%20Mistral.pdf",DataVersion="09/2014",DocumentSha256="753034781e5def7bbd2e1e5a9d8fd8f423254f603596fc74e1b2cf55653887d6",Conditions="Capacidade e dimensões externas do catálogo; módulo de 17,5 mm; passo entre trilhos de 125 mm, sem uso em um trilho; origem e altura desenhadas são esquemáticas, sem cotas de furação OEM; sem certificação térmica/IP"}};}
public static List<EnclosureRating> Import(string path){return ComponentCsv.Import<EnclosureRating>(path,Header,r=>r.Validate(),r=>r.Manufacturer+"|"+r.Reference+"|"+r.DataVersion);}public static void Export(IEnumerable<EnclosureRating> rows,string path){ComponentCsv.Export(rows,path,Header,r=>r.Validate(),r=>r.Manufacturer+"|"+r.Reference+"|"+r.DataVersion);}
public static void Apply(Project p,Board b,EnclosureRating rating){p.Validate();if(!p.Boards.Contains(b)||rating==null)throw new InvalidDataException("Quadro ou referência ausente.");rating.Validate();var old=b.Enclosure;var oldBinding=b.EnclosureCatalogSelection;try{b.Enclosure=rating.Spec();b.EnclosureCatalogSelection=new EnclosureCatalogBinding{Rating=rating.Copy()};p.Validate();}catch{b.Enclosure=old;b.EnclosureCatalogSelection=oldBinding;throw;}}
public static void ApplyFootprint(Project p,Board b,Circuit c,DinFootprint input,int row,int column){p.Validate();if(!p.Boards.Contains(b)||!b.Circuits.Contains(c)||input==null)throw new InvalidDataException("Circuito/envelope ausente.");input.Validate();Project.Range(row,0,10000,"trilhoDIN");Project.Range(column,0,10000,"colunaDIN");var copy=input.Copy();copy.HardwareContext=Hardware(c);var old=c.DinFootprint;int modules=c.DinModules,oldRow=c.DinRow,oldColumn=c.DinColumn;try{c.DinFootprint=copy;c.DinModules=copy.WidthModules;c.DinRow=row;c.DinColumn=column;p.Validate();}catch{c.DinFootprint=old;c.DinModules=modules;c.DinRow=oldRow;c.DinColumn=oldColumn;throw;}}
public static bool Matches(EnclosureRating r,EnclosureSpec s){return r.WidthMm==s.WidthMm&&r.HeightMm==s.HeightMm&&r.Rows==s.Rows&&r.ModulesPerRow==s.ModulesPerRow&&r.ModulePitchMm==s.ModulePitchMm&&r.RowPitchMm==s.RowPitchMm&&r.Manufacturer==s.Manufacturer&&r.Reference==s.Reference;}
public static EnclosureCatalogResult Evaluate(Project p,Board b){p.Validate();if(!p.Boards.Contains(b))throw new InvalidDataException("Quadro fora do projeto.");var result=new EnclosureCatalogResult();result.Issues.AddRange(Enclosures.Validate(b));var binding=b.EnclosureCatalogSelection;var r=binding==null?null:binding.Rating;if(r==null)result.Issues.Add("Invólucro real de catálogo não selecionado.");else{if(!new[]{r.Manufacturer,r.Reference,r.Variant,r.Source,r.DataVersion,r.Conditions}.All(Trace)||!Hash(r.DocumentSha256))result.Issues.Add("Rastreabilidade do catálogo incompleta.");if(!Matches(r,b.Enclosure))result.Issues.Add("Geometria/capacidade/referência alteradas após seleção; vínculo de catálogo pendente.");}foreach(var c in b.Circuits){var f=c.DinFootprint;if(f==null){result.Issues.Add(c.Id+": envelopeDIN desconhecido; default genérico2módulos não é largura comprovada.");continue;}if(f.ModulePitchMm!=b.Enclosure.ModulePitchMm)result.Issues.Add(c.Id+": passo do envelope DIN difere do passo do invólucro; confirme a largura física.");if(f.WidthModules!=c.DinModules||f.HardwareContext!=Hardware(c))result.Issues.Add(c.Id+": envelope/largura/hardware alterados após declaração.");if(f.CoversAccessories!=true||!new[]{f.Equipment,f.Reference,f.DataVersion,f.Conditions}.All(Trace))result.Issues.Add(c.Id+": declarar largura total rastreável incluindo acessórios/folgas.");}result.Accepted=result.Issues.Count==0;result.Status=result.Accepted?"Ocupação frontal verificada no escopo":"Ocupação incompleta/inválida";result.Detail=(r==null?"":r.Manufacturer+" / "+r.Reference+" / "+r.Variant+"; "+r.WidthMm+"×"+r.HeightMm+"×"+r.DepthMm+" mm externos; "+r.Rows+"×"+r.ModulesPerRow+" módulos de "+r.ModulePitchMm+"mm, passo entre trilhos="+r.RowPitchMm+"mm (não usado em1trilho); "+r.Source+" / "+r.DataVersion+"; SHA256doc="+r.DocumentSha256+"; "+r.Conditions+". Limites anotados: "+r.AnnotatedMaxCurrentA+" A / "+r.AnnotatedDissipationW+" W; não comprovam dissipação da montagem. ")+String.Join("; ",result.Issues)+". Vista frontal em gradeDIN, posições esquemáticas sem cotasOEM de origem/furação. Profundidade externa não é profundidade útil. Não comprova térmica,IP,corrente admissível,3D ou montagem/fabricação; verificar instalação e folgas reais.";return result;}
public static string Svg(Project p,Board b,string title){var result=Evaluate(p,b);string svg=Enclosures.Svg(p,b,title);var binding=b.EnclosureCatalogSelection;var rating=binding==null?null:binding.Rating;bool known=rating!=null&&Matches(rating,b.Enclosure);string label=known?rating.Manufacturer+" / "+rating.Reference+"; externo "+rating.WidthMm+"×"+rating.HeightMm+"×"+rating.DepthMm+"mm":"Geometria declarada; catálogo pendente";var culture=CultureInfo.InvariantCulture;string y=(b.Enclosure.HeightMm+25).ToString("0.###",culture);string pattern="<text x=\"10\" y=\""+y+"\" font-size=\"14\">.*?</text>";svg=System.Text.RegularExpressions.Regex.Replace(svg,pattern,"<text x=\"10\" y=\""+y+"\" font-size=\"8\">"+System.Security.SecurityElement.Escape(label)+"</text>");svg=svg.Replace("font-size=\"11\">Vista geométrica genérica; sem certificação térmica, IP ou montagem.","font-size=\"8\">Frontal esquemática; sem cotas de montagem/furação.");svg=svg.Replace("font-size=\"11\">Avisos de ocupação: "+Enclosures.Validate(b).Count+". Confira no aplicativo antes de montar.","font-size=\"8\">"+(result.Accepted?"Ocupação verificada no escopo.":"Pendências de ocupação: "+result.Issues.Count+".")+" Sem ensaio térmico/IP/3D.");int index=svg.IndexOf("</title>",StringComparison.Ordinal)+8;return svg.Insert(index,"<desc>"+System.Security.SecurityElement.Escape(result.Status+". "+result.Detail)+"</desc>");}
public static void AppendReport(Project p,Study study,StringBuilder text,IEnumerable<string> selected){var ids=selected==null?null:new HashSet<string>(selected);foreach(var b in p.Boards){if(b.EnclosureCatalogSelection==null||(ids!=null&&!b.Circuits.Any(c=>ids.Contains(c.Id))))continue;var result=Evaluate(p,b);text.AppendLine("\r\nINVÓLUCRO E OCUPAÇÃO FRONTAL — "+b.Id+" / "+EngineId);text.AppendLine(result.Status+". "+result.Detail);foreach(var c in b.Circuits){var f=c.DinFootprint;text.AppendLine(c.Id+": módulos="+c.DinModules+"; trilho/coluna="+c.DinRow+"/"+c.DinColumn+" (0/0automático); "+(f==null?"envelope desconhecido":f.Equipment+" / "+f.Reference+" / "+f.DataVersion+" / "+f.Conditions));}text.AppendLine("Ocupação do quadro completo, incluindo circuitos não selecionados, pois compartilham espaço físico.");}}
}
